-- Complete lessons 31-40 with bilingual priority rules, tips, quizzes and matching media.
BEGIN;
WITH data (lesson_number,summary_nl,summary_fa,rule_nl,rule_fa,tip_nl,tip_fa,image_src,question_nl,question_fa,option_1_nl,option_1_fa,option_2_nl,option_2_fa,option_3_nl,option_3_fa,correct_option,explanation_nl,explanation_fa) AS (VALUES
 (31,'Op gelijkwaardige kruispunten gaat verkeer van rechts voor.','در تقاطع‌های هم‌ارزش، وسیله‌ای که از راست می‌آید حق تقدم دارد.','Geef voorrang aan bestuurders van rechts, tenzij borden, haaientanden, verkeerslichten of een andere regel iets anders bepalen.','به راننده‌ای که از راست می‌آید راه بدهید، مگر تابلو، دندان‌های کوسه، چراغ یا قاعده دیگری خلاف آن باشد.','Kijk eerst naar borden en markeringen; pas daarna de regel rechts gaat voor toe.','ابتدا تابلو و خط‌کشی را بررسی کنید و سپس قاعده تقدم از راست را اجرا کنید.','/images/theory-016-right-before-left.webp','Wie heeft op een gelijkwaardig kruispunt voorrang?','در تقاطع هم‌ارزش چه کسی حق تقدم دارد؟','Verkeer van links','وسیله از چپ','Verkeer van rechts','وسیله از راست','De grootste auto','بزرگ‌ترین خودرو',1,'Op een gelijkwaardig kruispunt gaat verkeer van rechts voor.','در تقاطع هم‌ارزش، ترافیک از راست مقدم است.'),
 (32,'Haaientanden betekenen dat je voorrang moet verlenen.','دندان‌های کوسه یعنی باید حق تقدم بدهید.','Stop zo nodig vóór de haaientanden en laat bestuurders op de kruisende weg voorgaan.','در صورت نیاز پیش از دندان‌های کوسه بایستید و به رانندگان راه متقاطع تقدم دهید.','Rijd pas door als de hele kruisende rijbaan vrij is.','فقط وقتی تمام مسیر متقاطع آزاد است حرکت کنید.','/images/theory-017-shark-teeth.webp','Wat betekenen haaientanden?','دندان‌های کوسه چه معنایی دارند؟','Voorrang verlenen','دادن حق تقدم','Parkeren','پارک کردن','Altijd stoppen en wachten','همیشه توقف و انتظار',0,'Haaientanden verplichten je om voorrang te verlenen; stoppen is alleen nodig als dat nodig is.','دندان‌های کوسه الزام به دادن تقدم دارند؛ توقف فقط در صورت نیاز لازم است.'),
 (33,'Op een voorrangsweg heeft verkeer op de voorrangsweg voorrang op zijwegen.','در جاده دارای حق تقدم، ترافیک جاده اصلی بر راه‌های فرعی مقدم است.','Volg de voorrangsborden en let op het verloop van de voorrangsweg bij een bocht.','تابلوهای تقدم را رعایت کنید و هنگام پیچیدن مسیر جاده اصلی را دنبال کنید.','De voorrangsweg eindigt pas bij een einde-bord of een andere regeling.','جاده دارای تقدم تا تابلوی پایان یا قاعده دیگر ادامه دارد.','/images/theory-018-priority-road.webp','Wanneer eindigt een voorrangsweg?','جاده دارای حق تقدم چه زمانی پایان می‌یابد؟','Bij ieder kruispunt','در هر تقاطع','Bij een einde-voorrangsweg-bord of andere regeling','با تابلوی پایان تقدم یا قاعده دیگر','Als je afslaat','وقتی بپیچید',1,'Een voorrangsweg blijft gelden totdat de regeling eindigt of wordt gewijzigd.','حق تقدم جاده تا پایان یا تغییر مقررات معتبر است.'),
 (34,'Een stopbord verplicht volledig stoppen vóór de stopstreep of kruising.','تابلوی ایست الزام به توقف کامل پیش از خط ایست یا تقاطع دارد.','Stop ook als je geen verkeer ziet; kijk daarna opnieuw en rijd alleen veilig door.','حتی اگر ترافیکی نمی‌بینید کامل بایستید؛ سپس دوباره نگاه و فقط ایمن حرکت کنید.','Rollen over de stopstreep is geen volledige stop.','عبور غلتان از خط ایست، توقف کامل نیست.','/images/theory-019-stop-sign.webp','Wat moet je doen bij een stopbord?','در برابر تابلوی ایست چه باید کرد؟','Snel doorrijden','سریع عبور کردن','Volledig stoppen en voorrang verlenen','توقف کامل و دادن تقدم','Alleen richting aangeven','فقط راهنما زدن',1,'Bij STOP moet het voertuig volledig stilstaan vóór je verdergaat.','در برابر ایست، خودرو باید کاملاً متوقف شود.'),
 (35,'Een uitritconstructie is een bijzondere manoeuvre; al het overige verkeer gaat voor.','خروجی ملک یک مانور ویژه است؛ تمام ترافیک دیگر مقدم است.','Bij het verlaten van een uitrit geef je voorrang aan voetgangers, fietsers en bestuurders op de weg.','هنگام خروج از ملک به عابر، دوچرخه‌سوار و همه رانندگان راه تقدم بدهید.','Rijd stapvoets en let op trottoir en fietspad dat je kruist.','آهسته حرکت کنید و به پیاده‌رو و مسیر دوچرخه‌ای که قطع می‌کنید توجه کنید.','/images/theory-020-driveway-exit.webp','Wie heeft voorrang bij het verlaten van een uitrit?','هنگام خروج از ملک چه کسی مقدم است؟','Jij altijd','همیشه شما','Al het overige verkeer','تمام ترافیک دیگر','Alleen verkeer van rechts','فقط ترافیک از راست',1,'Een uitrit verlaten is een bijzondere manoeuvre: je laat iedereen voorgaan.','خروج از ملک مانور ویژه است و باید به همه راه بدهید.'),
 (36,'Van een onverharde weg naar een verharde weg geef je voorrang.','از راه خاکی به راه آسفالته باید حق تقدم بدهید.','De bestuurder op de verharde weg gaat voor, ook als die van links komt.','راننده راه آسفالته مقدم است، حتی اگر از چپ بیاید.','De ondergrond bepaalt hier de regel; kijk dus niet alleen naar links en rechts.','در اینجا نوع سطح راه تعیین‌کننده است؛ فقط چپ و راست را نگاه نکنید.','/images/Van onverharde zijweg naar asfaltweg.jpg','Wie heeft voorrang als je van onverhard naar verhard rijdt?','وقتی از راه خاکی به آسفالته می‌روید چه کسی مقدم است؟','Verkeer op de verharde weg','ترافیک راه آسفالته','Verkeer van rechts','ترافیک از راست','Niemand','هیچ‌کس',0,'Bij de overgang van onverhard naar verhard moet je verkeer op de verharde weg voor laten gaan.','در گذر از راه خاکی به آسفالته باید به ترافیک راه آسفالته تقدم داد.'),
 (37,'Een tram heeft op een gelijkwaardig kruispunt in beginsel voorrang.','تراموا در تقاطع هم‌ارزش اصولاً حق تقدم دارد.','Geef een tram voorrang, behalve wanneer borden, lichten of haaientanden een andere regeling geven.','به تراموا راه بدهید، مگر تابلو، چراغ یا دندان کوسه قاعده دیگری تعیین کند.','Controleer altijd de verkeerslichten en borden; die gaan vóór de hoofdregel.','همیشه چراغ و تابلو را بررسی کنید؛ آن‌ها بر قاعده اصلی مقدم‌اند.','/images/Twee autos rechtdoor op gelijkwaardig kruispunt.jpg','Wie heeft meestal voorrang op een gelijkwaardig kruispunt?','در تقاطع هم‌ارزش معمولاً چه کسی مقدم است؟','Een tram','تراموا','Een fietser altijd','همیشه دوچرخه‌سوار','De zwaarste auto','سنگین‌ترین خودرو',0,'Een tram heeft op een gelijkwaardig kruispunt voorrang, tenzij de regeling anders bepaalt.','تراموا در تقاطع هم‌ارزش مقدم است مگر مقررات خلاف آن باشد.'),
 (38,'Een bus die binnen de bebouwde kom van een halte wegrijdt moet je gelegenheid geven.','باید به اتوبوسی که در محدوده شهری از ایستگاه حرکت می‌کند فرصت ادغام بدهید.','Als de bus richting aangeeft en binnen de bebouwde kom wegrijdt, rem je zo nodig en laat je hem invoegen.','اگر اتوبوس راهنما بزند و داخل شهر از ایستگاه حرکت کند، در صورت نیاز ترمز کرده و اجازه ادغام دهید.','Geef ruimte zonder plotseling gevaarlijk te remmen; kijk ook naar fietsers.','بدون ترمز ناگهانی خطرناک فضا بدهید و مراقب دوچرخه‌سواران نیز باشید.','/images/theory-010-bus-lane.webp','Wat doe je als een bus binnen de bebouwde kom van een halte wil wegrijden?','اگر اتوبوس در شهر می‌خواهد از ایستگاه حرکت کند چه می‌کنید؟','De bus geen ruimte geven','راه ندادن','De bus gelegenheid geven in te voegen','فرصت ادغام دادن','Altijd links inhalen','همیشه از چپ سبقت گرفتن',1,'Binnen de bebouwde kom moet je een vertrekkende bus die richting aangeeft gelegenheid geven.','در محدوده شهری باید به اتوبوسِ راهنما‌زن فرصت ادغام بدهید.'),
 (39,'Voetgangers op een zebrapad hebben voorrang; ook duidelijk wachtende overstekers moet je laten voorgaan.','عابران روی خط عابر مقدم‌اند و عابرِ آشکارا منتظر عبور را نیز باید راه داد.','Nader een zebrapad langzaam en stop als een voetganger oversteekt of duidelijk wil oversteken.','آهسته به خط عابر نزدیک شوید و اگر عابر عبور می‌کند یا آشکارا قصد عبور دارد بایستید.','Let extra op kinderen en mensen die minder goed zichtbaar zijn.','به کودکان و افراد کم‌دید توجه ویژه کنید.','/images/Voetganger nadert zebrapad, auto stopt.jpg','Wanneer heeft een voetganger bij een zebrapad voorrang?','عابر در خط عابر چه زمانی مقدم است؟','Als hij oversteekt of duidelijk wil oversteken','وقتی عبور می‌کند یا آشکارا می‌خواهد عبور کند','Nooit','هرگز','Alleen als hij rent','فقط اگر بدود',0,'Op en bij een zebrapad moet je overstekende of duidelijk wachtende voetgangers voor laten gaan.','در خط عابر باید عابرِ در حال عبور یا آشکارا منتظر را راه داد.'),
 (40,'Een bijzondere manoeuvre, zoals keren of achteruitrijden, vereist voorrang verlenen aan iedereen.','مانور ویژه مانند دور زدن یا دنده‌عقب مستلزم دادن تقدم به همه است.','Kijk rondom, geef richting aan en laat al het overige verkeer voorgaan tijdens de manoeuvre.','اطراف را نگاه کنید، راهنما بزنید و هنگام مانور به تمام ترافیک دیگر تقدم دهید.','Voer de manoeuvre alleen uit als je de situatie volledig kunt overzien.','مانور را فقط وقتی انجام دهید که وضعیت را کاملاً ببینید.','/images/theory-004-mirrors-blind-spot.webp','Wat geldt bij een bijzondere manoeuvre?','در مانور ویژه چه قاعده‌ای است؟','Jij hebt voorrang','شما مقدم هستید','Je verleent iedereen voorrang','به همه تقدم می‌دهید','Alleen rechts heeft voorrang','فقط راست مقدم است',1,'Bij iedere bijzondere manoeuvre moet je al het overige verkeer voor laten gaan.','در هر مانور ویژه باید به تمام ترافیک دیگر راه بدهید.')
),release AS (SELECT id FROM content_releases WHERE version=1)
UPDATE course_lessons lesson SET summary=jsonb_build_object('nl',data.summary_nl,'fa',data.summary_fa),content_blocks=jsonb_build_array(jsonb_build_object('type','rule','text',jsonb_build_object('nl',data.rule_nl,'fa',data.rule_fa)),jsonb_build_object('type','exam_tip','text',jsonb_build_object('nl',data.tip_nl,'fa',data.tip_fa)),jsonb_build_object('type','quiz','question',jsonb_build_object('nl',data.question_nl,'fa',data.question_fa),'options',jsonb_build_array(jsonb_build_object('nl',data.option_1_nl,'fa',data.option_1_fa),jsonb_build_object('nl',data.option_2_nl,'fa',data.option_2_fa),jsonb_build_object('nl',data.option_3_nl,'fa',data.option_3_fa)),'correctOption',data.correct_option,'explanation',jsonb_build_object('nl',data.explanation_nl,'fa',data.explanation_fa))),media=jsonb_build_array(jsonb_build_object('type','image','src',data.image_src,'alt',lesson.title)),updated_at=NOW() FROM data,release WHERE lesson.release_id=release.id AND lesson.lesson_number=data.lesson_number;
DO $check$ DECLARE n integer; BEGIN SELECT count(*) INTO n FROM course_lessons WHERE release_id=(SELECT id FROM content_releases WHERE version=1) AND lesson_number BETWEEN 31 AND 40 AND content_blocks->2->>'type'='quiz'; IF n<>10 THEN RAISE EXCEPTION 'Priority lessons validation failed: %',n; END IF; END $check$;
INSERT INTO schema_migrations(version,name) VALUES(12,'priority_lessons') ON CONFLICT(version) DO NOTHING;
COMMIT;

